from typing import List, Tuple

def minPath(grid: List[List[int]], k: int) -> List[int]:
    """
    Returns the lexicographically smallest path of length k in the grid.
    """
    if not grid or k <= 0:
        return []

    n = len(grid)
    # Directions: up, down, left, right
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # dp holds for each cell the best sequence (as a tuple) of current length
    # Initialize for length 1
    dp = [[(grid[i][j],) for j in range(n)] for i in range(n)]

    # If k == 1, just pick the smallest single value
    if k == 1:
        min_seq = min((dp[i][j] for i in range(n) for j in range(n)))
        return list(min_seq)

    for step in range(2, k + 1):
        new_dp = [[None for _ in range(n)] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                best_seq: Tuple[int, ...] = None
                # Look at all neighbours that could have produced a path of length step-1
                for di, dj in dirs:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < n and dp[ni][nj] is not None:
                        cand = dp[ni][nj] + (grid[i][j],)
                        if best_seq is None or cand < best_seq:
                            best_seq = cand
                new_dp[i][j] = best_seq
        dp = new_dp

    # After building sequences of length k, pick the globally smallest one
    best_overall = None
    for i in range(n):
        for j in range(n):
            seq = dp[i][j]
            if seq is not None:
                if best_overall is None or seq < best_overall:
                    best_overall = seq

    return list(best_overall) if best_overall is not None else []
